<script lang="ts">
 import {onMount} from 'svelte';import {historicalParcelReference} from '../../lib/parcel-reference';
 let inventory=$state<any[]>([]),shipments=$state<any[]>([]),jobs=$state<any[]>([]),status=$state('Loading…'),busy=$state(false),counts=$state<Record<string,number>>({}),tracking=$state<Record<string,string>>({}),confirmed=$state<Record<string,boolean>>({});
 async function get(path:string){const res=await fetch('/api/admin/'+path,{cache:'no-store'});if(!res.ok)throw Error();return await res.json();}
 async function load(){try{const [stock,shipping,review]=await Promise.all([get('inventory'),get('shipments'),get('jobs')]);inventory=stock.inventory;shipments=shipping.shipments;jobs=review.jobs;counts=Object.fromEntries(inventory.map(row=>[row.sku,row.on_hand]));status='';}catch{status='Seller tools are unavailable. Please try again later.';}}
 onMount(load);
 async function mutate(path:string,method:string,body:unknown){if(busy)return;busy=true;status='Saving…';try{const res=await fetch('/api/admin/'+path,{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!res.ok){status=res.status===409?'The stock or shipment changed. Reload and check its current state.':'Could not save. Check the entered details and try again.';return;}await load();status='Saved';}catch{status='Could not save. Please try again.';}finally{busy=false;}}
</script>
<div class="max-w-6xl mx-auto px-6 py-24 space-y-10"><h1 class="font-serif text-4xl">Seller preparation</h1><p role="status">{status}</p><button class="btn" disabled={busy} onclick={load}>Reload</button>
<section class="bg-white/5 border border-white/10 rounded-3xl p-6"><h2 class="font-serif text-2xl mb-6">Actual inventory</h2><p class="text-neutral-400 mb-4">Enter actual on-hand counts. Unknown stock stays zero. Counts cannot be lower than reserved units.</p><div class="overflow-x-auto"><table class="table"><thead><tr><th>SKU</th><th>On hand</th><th>Reserved</th><th>Available</th><th></th></tr></thead><tbody>{#each inventory as row}<tr><th class="break-all">{row.sku}</th><td><label class="sr-only" for={'stock-'+row.sku}>On hand for {row.sku}</label><input class="input w-24" id={'stock-'+row.sku} type="number" min={row.reserved} max="100000" step="1" bind:value={counts[row.sku]}/></td><td>{row.reserved}</td><td>{row.on_hand-row.reserved}</td><td><button class="btn btn-sm" disabled={busy || !Number.isInteger(counts[row.sku]) || counts[row.sku]<row.reserved} onclick={()=>mutate('inventory','PATCH',{sku:row.sku,onHand:counts[row.sku]})}>Save stock</button></td></tr>{/each}</tbody></table></div></section>
<section class="space-y-6"><h2 class="font-serif text-2xl">Paid shipments</h2>{#if !shipments.length}<p>No paid shipments loaded.</p>{/if}{#each shipments as shipment}{@const reference=historicalParcelReference(shipment.address?.country)}<article class="bg-white/5 border border-white/10 rounded-3xl p-6 space-y-4"><h3 class="break-all">{shipment.order_id}</h3><p class="break-words">{shipment.recipient?.name} · {shipment.address?.line1} · {shipment.address?.city} · {shipment.address?.postal_code} · {shipment.address?.country}</p><p>Status: {shipment.status}</p>{#each shipment.items as item}<p>{item.quantity} × {item.name}</p>{/each}{#if reference}<p class="text-neutral-400">Historical Thailand Post reference, 15 April 2022: assumed 1,300 g, zone {reference.zone}, {reference.amountTHB} THB. No fee was added to Checkout. This does not establish current service eligibility or purchase postage.</p>{:else}<p class="text-neutral-400">No international-table estimate for this destination.</p>{/if}
{#if shipment.status==='needs_address'}<p>Recipient address needs attention. Contact the customer before dispatch.</p>{:else}<a class="btn" href={'/api/admin/shipping-label?order_id='+shipment.order_id} target="_blank" rel="noopener">Open printable preparation document</a>{/if}
{#if shipment.status==='ready'}<label class="flex gap-3 items-start"><input class="checkbox" type="checkbox" bind:checked={confirmed[shipment.order_id]}/><span>I confirmed the actual address, parcel weight, today's carrier rate and service availability before dispatch.</span></label><label class="block" for={'tracking-'+shipment.order_id}>Tracking number</label><input class="input w-full" id={'tracking-'+shipment.order_id} maxlength="120" bind:value={tracking[shipment.order_id]}/><button class="btn btn-primary" disabled={busy || !confirmed[shipment.order_id] || !/^[A-Za-z0-9][A-Za-z0-9 -]{2,119}$/.test(tracking[shipment.order_id]??'')} onclick={()=>mutate('shipments','POST',{orderId:shipment.order_id,tracking:tracking[shipment.order_id]})}>Mark shipped</button>{:else if shipment.status==='shipped'}<p>Tracking: {shipment.tracking_number}</p>{/if}</article>{/each}</section>
<section><h2 class="font-serif text-2xl mb-6">Failed or review delivery jobs</h2><p class="text-neutral-400 mb-4">Inspect provider delivery and configuration before any manual retry. These tools do not resend jobs.</p><div class="overflow-x-auto"><table class="table"><thead><tr><th>ID</th><th>Topic</th><th>Status</th><th>Attempts</th></tr></thead><tbody>{#each jobs as job}<tr><td>{job.id}</td><td>{job.topic}</td><td>{job.status}</td><td>{job.attempts}</td></tr>{/each}</tbody></table></div></section></div>